import{_ as a,o as e,c as r,ag as d}from"./chunks/framework.Cu2CLAe3.js";const m=JSON.parse('{"title":"Comprehensive C Language Tutorial","description":"","frontmatter":{},"headers":[],"relativePath":"en/vol1-fundamentals/c_tutorials/index.md","filePath":"en/vol1-fundamentals/c_tutorials/index.md","lastUpdated":null}'),n={name:"en/vol1-fundamentals/c_tutorials/index.md"};function i(o,t,s,c,l,h){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="comprehensive-c-language-tutorial" tabindex="-1">Comprehensive C Language Tutorial <a class="header-anchor" href="#comprehensive-c-language-tutorial" aria-label="Permalink to &quot;Comprehensive C Language Tutorial&quot;">​</a></h1><p>If you are planning to learn or revisit C for any reason, and find the C crash course in the parent directory too fast-paced, consider this tutorial instead. It is more detailed and gradual than the crash course, and you can still pick and choose topics based on your interests.</p><h2 id="fundamentals" tabindex="-1">Fundamentals <a class="header-anchor" href="#fundamentals" aria-label="Permalink to &quot;Fundamentals&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Article</th><th>Description</th></tr></thead><tbody><tr><td>01</td><td><a href="./01-program-structure-and-compilation">Program Structure and Compilation Basics</a></td><td>Basic structure of C programs, the four stages of compilation, header file mechanisms, and basic I/O</td></tr><tr><td>02A</td><td><a href="./02A-data-types-basics">Data Type Basics: Integers and Memory</a></td><td>Integer family, signed vs. unsigned, fixed-width types, and sizeof</td></tr><tr><td>02B</td><td><a href="./02B-float-char-const-cast">Floating-Point, Characters, const, and Type Conversion</a></td><td>Floating-point precision, character encoding, the const qualifier, and implicit type conversion</td></tr><tr><td>03A</td><td><a href="./03A-operators-basics">Operator Basics: Making Data Move</a></td><td>Arithmetic, relational, and logical operators, short-circuit evaluation, and assignment operators</td></tr><tr><td>03B</td><td><a href="./03B-bitwise-and-evaluation">Bitwise Operations and Evaluation Order</a></td><td>Bitwise operations, shift caveats, precedence traps, and sequence points</td></tr><tr><td>04</td><td><a href="./04-control-flow">Control Flow: Teaching Programs to Choose and Repeat</a></td><td>Conditional branching, loops, switch fall-through, and the state machine pattern</td></tr><tr><td>05</td><td><a href="./05-function-basics">Function Basics and Parameter Passing</a></td><td>Function declaration/definition/calling, pass-by-value, pointer parameters, and recursion</td></tr><tr><td>06</td><td><a href="./06-scope-and-storage">Scope and Storage Classes</a></td><td>Scope rules, storage classes, linkage, and the three uses of static</td></tr><tr><td>07A</td><td><a href="./07A-pointer-essentials">Pointer Essentials: The World of Addresses</a></td><td>Memory model, address-of and dereference operators, pointer arithmetic, and distance calculation</td></tr><tr><td>07B</td><td><a href="./07B-pointers-arrays-const">Pointers, Arrays, const, and Null Pointers</a></td><td>Array-to-pointer decay, const and pointer combinations, NULL, and wild pointers</td></tr><tr><td>08A</td><td><a href="./08A-multi-level-pointers">Multi-Level Pointers and Declaration Reading</a></td><td>Multi-level pointer memory models, arrays of pointers vs. pointers to arrays, and cdecl reading rules</td></tr><tr><td>08B</td><td><a href="./08B-restrict-incomplete-types">restrict, Incomplete Types, and Struct Pointers</a></td><td>restrict optimization, forward declarations, and the opaque pointer pattern</td></tr><tr><td>09</td><td><a href="./09-function-pointers-and-callbacks">Function Pointers and the Callback Pattern</a></td><td>Function pointer declaration and usage, the callback pattern, and event-driven programming</td></tr><tr><td>10</td><td><a href="./10-arrays-deep-dive">Arrays Deep Dive</a></td><td>Memory layout, multi-dimensional arrays, variable-length arrays, and their relationship with pointers</td></tr><tr><td>11</td><td><a href="./11-c-strings-and-buffer-safety">C Strings and Buffer Safety</a></td><td><code>\\0</code> termination model, core string.h functions, and buffer overflow prevention</td></tr><tr><td>12</td><td><a href="./12-struct-and-memory-alignment">Structs and Memory Alignment</a></td><td>Struct definition, alignment padding rules, and flexible array members</td></tr><tr><td>13</td><td><a href="./13-union-enum-bitfield-typedef">Unions, Enums, Bit Fields, and typedef</a></td><td>Type punning, hardware register mapping, and comparison with C++ type-safe alternatives</td></tr><tr><td>14</td><td><a href="./14-dynamic-memory">Dynamic Memory Management</a></td><td>malloc/calloc/realloc/free, common memory errors, and debugging</td></tr><tr><td>15</td><td><a href="./15-preprocessor-and-multifile">Preprocessor and Multi-File Projects</a></td><td>Macros, conditional compilation, header guards, and modular multi-file projects</td></tr><tr><td>16</td><td><a href="./16-file-io-and-stdlib">File I/O and Standard Library Overview</a></td><td>File reading and writing, formatted I/O, and command-line argument processing</td></tr></tbody></table><h2 id="advanced-topics" tabindex="-1">Advanced Topics <a class="header-anchor" href="#advanced-topics" aria-label="Permalink to &quot;Advanced Topics&quot;">​</a></h2><p>Advanced topics are located in the <a href="./advanced_feature/">advanced_feature/</a> subdirectory, covering more in-depth subjects:</p><table tabindex="0"><thead><tr><th>#</th><th>Article</th><th>Description</th></tr></thead><tbody><tr><td>01</td><td><a href="./advanced_feature/01-arm-architecture-fundamentals">ARM Architecture and Structure Fundamentals</a></td><td>ARM Cortex-M instruction set, registers, exception vector tables, and processor modes</td></tr><tr><td>02</td><td><a href="./advanced_feature/02-cache-and-memory-hierarchy">Cache Mechanisms and Memory Hierarchy</a></td><td>Cache lines, mapping strategies, the MESI protocol, and cache-friendly programming</td></tr><tr><td>03</td><td><a href="./advanced_feature/03-c-traps-and-pitfalls">C Language Traps and Common Errors</a></td><td>Syntax and semantic traps, compiler behavior, and standard specification analysis</td></tr><tr><td>04</td><td><a href="./advanced_feature/04-oop-in-c">Implementing OOP in C</a></td><td>Simulating classes with structs and function pointers, encapsulation, inheritance, and polymorphism</td></tr><tr><td>05</td><td><a href="./advanced_feature/05-handmade-dynamic-array">Building a Dynamic Array from Scratch</a></td><td>Type-safe dynamic array library, memory resizing, and API design</td></tr><tr><td>06</td><td><a href="./advanced_feature/06-handmade-linked-list">Building a Singly Linked List from Scratch</a></td><td>Insertion, deletion, and search algorithms, along with sentinel node techniques</td></tr><tr><td>07</td><td><a href="./advanced_feature/07-embedded-c-patterns">Embedded C Programming Patterns</a></td><td>Register access, volatile, interrupt safety, and peripheral abstraction layers</td></tr><tr><td>08</td><td><a href="./advanced_feature/08-reusable-c-code">Building Reusable C Code</a></td><td>Modular design, opaque pointers, and platform abstraction layers</td></tr></tbody></table>',7)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
